body.query:
	mutation AddContactToCampaignHook($id: ID!, $contact: JSON!) {
		addContactToCampaignHook(id: $id, contact: $contact)
}

mutation createCampaign($name: String!) {
	createCampaign(name: $name) {
		_id
		name
		status
		createdAt
		provider
		startAt
		estimatedEnd
	}
}

query all_campaigns {
	all_campaigns {
		_id
		name
		status
		createdAt
		stats {
			mailsSent
			uniqueOpensPercent
			opens
			linkClickedPercent
			repliedPercent
			bouncedPercent
			unsubscribePercent
			progressPercent
		}
	}
}

mutation AddContactsToListHook($id: ID!, $contact: JSON!) {
	addContactsToListHook(id: $id, contact: $contact)
}

query contact_lists{
	contact_lists{
		_id
		name
		contactCount
		fields
		usedInCampaign
	}
}
